	lhs[i][j][k][AA][2][0] = - tmp2 * fjac[i][j-1][k][2][0]
	  - tmp1 * njac[i][j-1][k][2][0];
	lhs[i][j][k][AA][2][1] = - tmp2 * fjac[i][j-1][k][2][1]
	  - tmp1 * njac[i][j-1][k][2][1];
	lhs[i][j][k][AA][2][2] = - tmp2 * fjac[i][j-1][k][2][2]
