  int nthreads = 1;
  double navg, mflops;

  double tmax;
  boolean verified;
  char class;
  FILE *fp;

  printf("\n\n NAS Parallel Benchmarks 3.0 structured OpenMP C version"
	 " - BT Benchmark\n\n");

