  initialize();
  lhsinit();
  exact_rhs();

  adi();

  initialize();

  timer_clear(1);
  timer_start(1);

  for (step = 1; step <= niter; step++) {

    if (step%20 == 0 || step == 1) {
      printf(" Time step %4d\n", step);
    }
    adi();
  }

{   
#if defined(_OPENMP)
  nthreads = omp_get_num_threads();
#endif 
} 

  timer_stop(1);
