	lhs[i][j][k][BB][3][4] = tmp1 * 2.0 * njac[i][j][k][3][4];

	lhs[i][j][k][BB][4][0] = tmp1 * 2.0 * njac[i][j][k][4][0];
	lhs[i][j][k][BB][4][1] = tmp1 * 2.0 * njac[i][j][k][4][1];
