	  - tmp1 * njac[i][j+1][k][1][0];
	lhs[i][j][k][CC][1][1] =  tmp2 * fjac[i][j+1][k][1][1]
	  - tmp1 * njac[i][j+1][k][1][1]
	  - tmp1 * dy2;
	lhs[i][j][k][CC][1][2] =  tmp2 * fjac[i][j+1][k][1][2]
	  - tmp1 * njac[i][j+1][k][1][2];
	lhs[i][j][k][CC][1][3] =  tmp2 * fjac[i][j+1][k][1][3]
	  - tmp1 * njac[i][j+1][k][1][3];
