    boolean verified;

    int i, j, l;
    FILE *fp;

    timer_clear(T_BENCH);
    timer_clear(T_INIT);

    timer_start(T_INIT);

    printf("\n\n NAS Parallel Benchmarks 3.0 structured OpenMP C version"
	   " - MG Benchmark\n\n");

